 * @method
 * @name hideAlertPubOfrRslt
 * @description hide Alert Pub Ofr Rslt 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideAlertPubOfrRslt = function () {
    $c.util.setSessionStorage("alertPubOfrRslt1Day", "alertPubOfrRslt1Day");
    hideLayer('#divAlertPubOfrRslt');
};

/**
 * @method
 * @name checkListDd
 * @description check List Dd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkListDd = async function () {

    scwin.xmlhttp = scwin.GetXmlHttpObject();

    if (scwin.xmlhttp == null) {
        await $c.win.alert ("Ajax를 지원하지 않는 브라우저입니다.\n 헬프데스크에 문의하시기 바랍니다!");
        return;
    }

    const frm = $c.util.getComponent('pubofrRsltForm');
    const listSchdlDd = $c.util.getComponent('ipt_listSchdlDd').getValue();
    if(($c.util.getComponent('ipt_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('ipt_listSchdlDd').getValue())) === ''){
        await $c.win.alert('상장(희망)일을 입력하십시오');
        return;

    }

    // KBoY 2014-12-03 SrM-000090012 201412만 중복 신청 가능.
    if(is201412(listSchdlDd)){
        await $c.win.alert('신청 가능한 희망일입니다.');
        $c.util.getComponent("dma_registerReq").set("possibleYn", 'Y');
    }else{
        const url="/listInvstg/pubOfrSchdl.do?method=checkListDd&listSchdlDd=" + listSchdlDd + "&bzProcsNo="+"" + dma_pageContext.get("bzProcsNo") + "";
        scwin.xmlhttp.onreadystatechange=scwin.stateChanged;
        scwin.xmlhttp.open("POST",url,true);
        scwin.xmlhttp.send(null);
    }

};

/**
 * @method
 * @name stateChanged
 * @description state Changed 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stateChanged = async function () {
    const frm = $c.util.getComponent('pubofrRsltForm');
    if (scwin.xmlhttp.readyState === 4) {
        const returnText = scwin.trim(scwin.xmlhttp.responseText);
        if (returnText === 'N') {
            await $c.win.alert('이미 신청중인 상장(희망)일입니다.\n 다른 날짜를 선택해 주십시오.');
            $c.util.getComponent("ipt_listSchdlDd").setValue('');
        } else {
            await $c.win.alert('신청 가능한 희망일입니다.');
            $c.util.getComponent("dma_registerReq").set("possibleYn", 'Y');
        }
    }
};

/**
 * @method
 * @name GetXmlHttpObject
 * @description Get Xml Http Object 처리
 * @returns {void}
 * @hidden N
 */
scwin.GetXmlHttpObject = function () {
    if (XMLHttpRequest) {
        return new XMLHttpRequest();
    }

    return null;
};

/**
 * @method
 * @name isCheckRadio
 * @description is Check Radio 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.isCheckRadio = function (ver) {
    for (let i = 0; i < ver.getItemCount(); i++) {
        if (ver[i].checked) {
            return true;
        }
    }
    return false;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const frm = $c.util.getComponent('pubofrRsltForm');
    if ('07' === '' + dma_basicComInfo.get("listTpClssCd") + '') {
        await $c.win.alert('SPAC-소멸합병인 경우 공모없음으로 저장합니다.');
        $c.util.getComponent("ipt_chkPubofr").setValue(true);
        $c.util.getComponent("dma_registerReq").set("pubofrYn", 'N');
    } else {
        const pubofrYn = $c.util.getComponent("dma_registerReq").get("pubofrYn");
        const process = $c.util.getComponent("dma_registerReq").get("process");
        const pubofrWrtTpCd = $c.util.getComponent("dma_registerReq").get("pubofrWrtTpCd");
        if (process === '2' && pubofrWrtTpCd === '') {
            $c.util.getComponent("dma_registerReq").set("isurCd", $c.util.getComponent('ipt_isurCd').getValue());
            $c.util.getComponent("dma_registerReq").set("pubofrWrtTpCd", '1');
        }
        if (($c.util.getComponent('ipt_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('ipt_listSchdlDd').getValue())) === '') {
            await $c.win.alert('상장(희망)일을 입력하여 주십시오');
            return;
        }
        if (pubofrYn === 'N') {
            if (!await $c.win.confirm('공모없음이 체크되어 있습니다. \n 계속 진행할 경우 입력내용이 모두 삭제 됩니다. 계속 하시겠습니까?')) {
                return;
            }
            if (process === '2') {
                if (($c.util.getComponent('ipt_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('ipt_listSchdlDd').getValue())) !== '') {
                    if ($c.util.getComponent("dma_registerReq").get("possibleYn") !== 'Y') {
                        await $c.win.alert('상장(희망)일 중복체크를 하여 주십시오');
                        return;
                    }
                }
            }
        } else {
            $c.util.getComponent("dma_registerReq").set("pubofrYn", 'Y');
            if (($c.util.getComponent('cal_pubofrSchdlStrtDd').getValue() == null ? '' : String($c.util.getComponent('cal_pubofrSchdlStrtDd').getValue())) === '') {
                await $c.win.alert('청약일정 시작일을 입력하여 주십시오');
                return;
            }
            if (process === '2') {
                if (($c.util.getComponent('ipt_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('ipt_listSchdlDd').getValue())) !== '') {
                    if ($c.util.getComponent("dma_registerReq").get("possibleYn") !== 'Y') {
                        await $c.win.alert('상장(희망)일 중복체크를 하여 주십시오');
                        return;
                    }
                }
            }
            if (await scwin.checkRslt()) {
                return;
            }
            if (!(String(($c.util.getComponent('rd_nparvalstkYn'))?.getValue?.() ?? "") !== "")) {
                await $c.win.alert('무액면주식여부는 필수 입니다.');
                return;
            }
        }
    }
    if ($c.util.getComponent("dma_registerReq").get("pubofrWrtTpCd") === '1') {
        $c.util.getComponent("dma_registerReq").set("method", 'insertPubOfrRslt');
    } else {
        if ($c.util.getComponent("dma_registerReq").get("pubofrWrtTpCd") === '2') {
            $c.util.getComponent("dma_registerReq").set("method", 'updatePubOfrRslt');
        }
    }
    frm.action = 'pubOfrRslt.do';
    const nr = await scwin.tx_fn_register();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil55100n/jldfil55100n.xml", { "pubofrYn": 'N', "isurCd": $c.util.getComponent('ipt_isurCd').getValue(), "pubofrWrtTpCd": '1', "method": 'insertPubOfrRslt' });
    }
};

/**
 * @method
 * @name checkRslt
 * @description check Rslt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkRslt = async function () {
    const frm = (document.pubofrRsltForm || { elements: [] });
    const pubofrYn = $c.util.getComponent("dma_registerReq").get("pubofrYn");
    if (pubofrYn === "N") {
        return;
    }
    if (($c.util.getComponent('ipt_pubofrPrc').getValue() == null ? '' : String($c.util.getComponent('ipt_pubofrPrc').getValue())) === '' || $c.util.getComponent('ipt_pubofrPrc').getValue()=== "0") {
        await $c.win.alert("공모가액 항목의 정확한 수량 혹은 금액을 입력하여야 합니다.");
        return true;
    }
    if (($c.util.getComponent('ipt_pubofrShrsAgg').getValue() == null ? '' : String($c.util.getComponent('ipt_pubofrShrsAgg').getValue())) === '' || $c.util.getComponent('ipt_pubofrShrsAgg').getValue()=== "0") {
        await $c.win.alert("주식수 총액 항목의 정확한 수량 혹은 금액을 입력하여야 합니다.");
        return true;
    }
    if (($c.util.getComponent('ipt_totPubofrAmt').getValue() == null ? '' : String($c.util.getComponent('ipt_totPubofrAmt').getValue())) === '' || $c.util.getComponent('ipt_totPubofrAmt').getValue()=== "0") {
        await $c.win.alert("공모금액 총액 항목의 정확한 수량 혹은 금액을 입력하여야 합니다.");
        return true;
    }
};

/**
 * @method
 * @name toList
 * @description to List 처리
