    $c.util.getComponent("dma_registerReq").set("method", "searchNewListInvstgMaster");
    const nr = await scwin.tx_fn_toList();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil55000/jldfil55000.xml", { "method": "searchNewListInvstgMaster" });
    }
};

/**
 * @method
 * @name checkPubofrYn
 * @description check Pubofr Yn 처리
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.checkPubofrYn = function (value) {
    if (value) {
        $c.util.getComponent("dma_registerReq").set("pubofrYn", 'N');
    } else {
        $c.util.getComponent("dma_registerReq").set("pubofrYn", 'Y');
    }
};

/**
