        return;
    }
    const frm = (document.pubofrRsltForm || { elements: [] });
    frm.action = "pubOfrRslt.do";
    $c.util.getComponent("dma_registerReq").set("method", "searchPubOfrRslt");
    $c.util.getComponent("dma_registerReq").set("bzProcsNo", bzProcsNo);
    $c.util.getComponent("dma_registerReq").set("isurCd", isurCd);
    const nr = await scwin.tx_fn_pubofrRslt();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil55100n/jldfil55100n.xml", { "method": "searchPubOfrRslt", "bzProcsNo": bzProcsNo, "isurCd": isurCd });
    }
};

