/**
 * @method
 * @name trim
 * @description trim 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.trim = function (str) {
    str = str.replace(/^\s*/, '').replace(/\s*$/, '');
    return str;
};

/**
 * @method
 * @name checkNumber
 * @description check Number 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumber = async function (obj) {
    if (/[^0123456789.]/g.test(obj.value)) {
        await $c.win.alert("숫자가 아닙니다.\n\n0-9의 정수만 허용합니다.");
        obj.select();
        return;
    }
};

/**
 * @method
 * @name checkNumber1
 * @description check Number1 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumber1 = async function (obj) {
    if (/[^0123456789.]/g.test(obj.value)) {
        await $c.win.alert("숫자가 아닙니다.\n\n0-9의 정수만 허용합니다.");
        obj.select();
        return;
    }
    if (parseFloat(obj.value) > 100) {
        await $c.win.alert('100% 이하 소수로 입력하시기 바랍니다.');
        obj.select();
        return;
    }
    if (obj.value.indexOf(".") > 0) {
        if (obj.value.substring(obj.value.indexOf(".") + 1).length > 6) {
            await $c.win.alert('소수 6자리까지 입력할 수 있습니다');
            obj.select();
            return;
        }
    } else {
        if (obj.value.length > 3) {
            await $c.win.alert('100% 이하 소수로 입력하시기 바랍니다.');
            obj.select();
            return;
        }
    }
};
